  const outline = side => { const pts = []; for (let k = 0; k <= 60; k++) { const s = k / 60; pts.push([cx + side * half(s), yAt(s)]); } return pts; };
  const fillHalf = (side, col) => { c.fillStyle = col; c.beginPath(); c.moveTo(cx, yAt(0)); for (const p of outline(side)) c.lineTo(...p); c.lineTo(cx, yAt(1)); c.closePath(); c.fill(); };
  fillHalf(-1, '#5e9e48'); fillHalf(1, '#8cc85f');
