// One frond: a spine that arches out and sags under its own weight, lined with long leaflets
// angled toward the tip. Upper faces are bright yellow-green, the inner and lower ones darker.
function frond(o, d0, len, droop, tint) {
  const segs = 26, pos = [], col = [];
  const up = new V3(0, 1, 0);
  const spine = t => o.clone().addScaledVector(d0, len * t).addScaledVector(up, -droop * len * t * t);
  const cBase = new THREE.Color('#4f9631'), cTip = new THREE.Color('#bfe04e'), cDark = new THREE.Color('#2f6b2a');
  for (let i = 0; i < segs; i++) {
    const t0 = i / segs, t1 = (i + 1) / segs, p0 = spine(t0), p1 = spine(t1);
    const dir = p1.clone().sub(p0).normalize();
    const side = new V3().crossVectors(dir, up).normalize();
    const wl = 1.05 * Math.pow(Math.sin(Math.PI * Math.min(1, t0 * 0.95 + 0.07)), 0.55);
    for (const sgn of [-1, 1]) {
      const tip = p0.clone().addScaledVector(side, sgn * wl).addScaledVector(dir, 0.5 * wl).add(new V3(0, -0.42 * wl, 0));
      const c0 = cBase.clone().lerp(cTip, Math.min(1, t0 * 1.25 + 0.1)).offsetHSL(0, 0, tint);
      const c1 = sgn > 0 ? c0.clone().lerp(cDark, 0.32) : c0;
      const pm = p0.clone().lerp(p1, 0.5);
      pos.push(...p0.toArray(), ...pm.toArray(), ...tip.toArray(), ...pm.toArray(), ...p1.toArray(), ...tip.toArray());
      for (let k = 0; k < 6; k++) col.push(c1.r, c1.g, c1.b);
    }
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setAttribute('color', new THREE.Float32BufferAttribute(col, 3));
  g.computeVertexNormals();
  return g;
}
